患者趋势.css:
* { box-sizing: border-box; }
body { margin: 0px; background: rgb(237, 242, 248); color: rgb(36, 53, 78); font: 14px / 1.6 -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei", sans-serif; }
body { font-variant-numeric: tabular-nums; }
* { box-sizing: border-box; }
body { margin: 0px; background: rgb(237, 242, 248); color: rgb(36, 53, 78); font: 14px / 1.6 -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei", sans-serif; }
button, input, select, textarea { font: inherit; }
button, .button { min-height: 44px; padding: 9px 15px; border: 1px solid rgb(195, 206, 222); background: rgb(255, 255, 255); border-radius: 6px; color: rgb(39, 69, 110); cursor: pointer; display: inline-flex; align-items: center; justify-content: center; text-decoration: none; gap: 6px; }
button:disabled { opacity: 0.5; cursor: not-allowed; }
.primary { background: rgb(53, 103, 214); color: rgb(255, 255, 255); border-color: rgb(53, 103, 214); }
a { color: rgb(40, 91, 188); text-decoration: none; }
a:hover { text-decoration: underline; }
button:hover:not(:disabled) { filter: brightness(0.97); }
:focus-visible { outline: rgb(109, 141, 241) solid 3px; outline-offset: 3px; }
h1 { font-size: 25px; line-height: 1.3; margin: 3px 0px 8px; }
h2 { font-size: 18px; margin: 0px 0px 16px; }
p { margin: 8px 0px; }
small, .small { font-size: 12px; }
.muted { color: rgb(92, 110, 133); }
.eyebrow { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; color: rgb(87, 110, 147); margin: 0px 0px 6px; }
.topbar { height: 64px; background: rgb(53, 103, 214); color: rgb(255, 255, 255); display: flex; align-items: center; justify-content: space-between; padding: 0px 28px; gap: 16px; }
.brand { display: flex; align-items: center; gap: 14px; font-size: 17px; }
.brand b { font-size: 23px; border-right: 1px solid rgba(255, 255, 255, 0.376); padding-right: 18px; }
.brand small { color: rgb(226, 236, 255); font-size: 14px; }
.account { display: flex; align-items: center; gap: 16px; }
.account button { background: transparent; border-color: rgb(196, 213, 255); color: rgb(255, 255, 255); }
.modulebar { min-height: 48px; background: rgb(255, 255, 255); border-bottom: 1px solid rgb(217, 225, 237); display: flex; align-items: center; gap: 24px; padding: 0px 28px; }
.modulebar > span:first-child { color: rgb(100, 116, 139); }
.modulebar strong { border-bottom: 3px solid rgb(53, 103, 214); padding: 11px 0px; }
.modulebar small { font-weight: 400; color: rgb(88, 109, 135); margin-left: 10px; }
.env { margin-left: auto; font-size: 12px; color: rgb(133, 80, 24); }
.shell { display: grid; grid-template-columns: 206px minmax(0px, 1fr); min-height: calc(-112px + 100vh); }
aside { background: rgb(249, 251, 254); border-right: 1px solid rgb(217, 225, 237); padding: 24px 12px; position: relative; }
.navtitle { font-size: 12px; color: rgb(105, 124, 150); padding: 0px 14px; margin-bottom: 16px; }
nav a { display: block; min-height: 46px; padding: 12px 14px; margin: 4px 0px; color: rgb(77, 98, 126); border-radius: 6px; }
nav a.active { background: rgb(228, 236, 252); color: rgb(36, 79, 169); font-weight: 600; border-left: 3px solid rgb(53, 103, 214); padding-left: 11px; }
.sidefoot { font-size: 12px; color: rgb(91, 108, 132); margin-top: 64px; padding: 14px; border-top: 1px solid rgb(217, 225, 237); }
.sidefoot span { display: block; margin-top: 8px; color: rgb(111, 126, 144); }
.content { padding: 28px; min-width: 0px; max-width: 1680px; width: 100%; margin: 0px auto; }
.pagehead { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 22px; }
.card { background: rgb(255, 255, 255); border: 1px solid rgb(220, 228, 239); border-radius: 8px; padding: 22px; margin-bottom: 20px; box-shadow: rgba(24, 50, 88, 0.02) 0px 1px 2px; min-width: 0px; }
.notice { background: rgb(237, 243, 255); color: rgb(48, 84, 141); border-width: 1px 1px 1px 3px; border-style: solid; border-color: rgb(201, 217, 247) rgb(201, 217, 247) rgb(201, 217, 247) rgb(77, 120, 220); border-image: initial; border-radius: 5px; padding: 12px 16px; margin: 0px 0px 20px; }
.toolbar { display: flex; align-items: center; gap: 12px; margin-bottom: 18px; flex-wrap: wrap; }
.toolbar label { margin: 0px; display: flex; gap: 10px; align-items: center; }
.toolbar input { max-width: 300px; }
.toolbar .muted { margin-left: auto; }
.tablewrap { overflow-x: auto; }
table { border-collapse: collapse; width: 100%; text-align: left; }
th { color: rgb(94, 112, 136); font-weight: 500; background: rgb(245, 248, 252); font-size: 12px; }
td, th { padding: 14px 12px; border-bottom: 1px solid rgb(229, 235, 244); vertical-align: middle; }
td { font-size: 13px; }
td small { display: block; color: rgb(96, 113, 138); font-size: 11px; max-width: 240px; overflow-wrap: anywhere; }
.bed { background: rgb(237, 243, 254); color: rgb(44, 91, 180); border-radius: 5px; padding: 7px 10px; font-weight: 700; }
.tag { display: inline-flex; align-items: center; padding: 3px 8px; background: rgb(233, 240, 253); color: rgb(54, 93, 157); border: 1px solid rgb(209, 223, 244); border-radius: 4px; font-size: 12px; line-height: 1.5; }
.tag.danger { background: rgb(255, 240, 239); color: rgb(167, 48, 45); border-color: rgb(237, 196, 192); }
.warning { background: rgb(255, 244, 223); color: rgb(133, 85, 24); border-color: rgb(234, 210, 171); }
.pager { display: flex; justify-content: flex-end; align-items: center; gap: 12px; padding-top: 16px; color: rgb(98, 115, 138); }
.empty { padding: 38px 16px; text-align: center; color: rgb(99, 117, 140); background: rgb(248, 250, 253); border-radius: 6px; }
.error { background: rgb(255, 240, 239); color: rgb(159, 41, 41); padding: 12px; border: 1px solid rgb(239, 194, 189); border-radius: 6px; overflow-wrap: anywhere; }
.workspace { display: grid; grid-template-columns: minmax(0px, 1.35fr) minmax(290px, 1fr); gap: 20px; }
.workspace td { font-size: 12px; }
.workspace .card { padding: 18px; }
dl { display: grid; grid-template-columns: 130px 1fr; gap: 12px; margin: 18px 0px; }
dt { color: rgb(91, 109, 133); }
dd { margin: 0px; overflow-wrap: anywhere; }
.missing { padding: 12px; background: rgb(255, 247, 233); color: rgb(125, 81, 24); border: 1px solid rgb(237, 219, 185); font-size: 13px; border-radius: 5px; }
.prediction { display: flex; justify-content: space-between; gap: 12px; border-bottom: 1px solid rgb(228, 234, 244); padding: 14px 0px; font-size: 13px; }
.prediction span { color: rgb(100, 116, 138); }
.workspace .button { margin-top: 18px; }
.back { display: inline-block; margin: 0px 0px 14px; }
.historyitem { display: block; text-align: left; width: 100%; margin: 7px 0px; }
.alertrow { display: grid; grid-template-columns: minmax(180px, 1fr) minmax(220px, 1.3fr) auto; gap: 20px; border-top: 1px solid rgb(229, 235, 244); padding: 20px 0px; align-items: center; }
.alertrow strong { display: block; }
.alertrow small { display: block; margin-top: 6px; color: rgb(97, 115, 139); }
.alertrow .tag { margin-bottom: 8px; }
.actions { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: 8px; }
.taskrow { border-top: 1px solid rgb(227, 234, 243); padding: 22px 0px; }
.tasktitle { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.tasktitle .muted { margin-left: auto; }
.states { display: grid; grid-template-columns: repeat(4, minmax(0px, 1fr)); gap: 12px; margin: 18px 0px; }
.states > div { padding: 12px; background: rgb(246, 249, 253); border: 1px solid rgb(226, 233, 244); border-radius: 6px; }
.states small { display: block; color: rgb(101, 120, 143); }
.states strong { font-size: 13px; }
.metrics { display: grid; grid-template-columns: repeat(4, minmax(0px, 1fr)); gap: 16px; margin-bottom: 24px; }
.metric { background: rgb(255, 255, 255); border: 1px solid rgb(220, 228, 239); border-radius: 8px; padding: 20px; color: rgb(52, 77, 113); }
.metric strong { display: block; font-size: 30px; line-height: 1.4; margin: 8px 0px; overflow-wrap: anywhere; }
.metric small { font-size: 13px; }
.metric span { font-size: 12px; color: rgb(100, 115, 138); }
.overlay { position: fixed; inset: 0px; background: rgba(17, 33, 61, 0.44); display: flex; justify-content: center; align-items: center; padding: 20px; z-index: 10; overflow: auto; }
.dialog { background: rgb(255, 255, 255); border-radius: 10px; width: 540px; max-width: 100%; padding: 26px; max-height: 90vh; overflow: auto; }
label { display: block; margin: 14px 0px; color: rgb(71, 92, 120); }
input, textarea, select { display: block; width: 100%; min-height: 44px; border: 1px solid rgb(186, 200, 220); background: rgb(255, 255, 255); border-radius: 5px; padding: 9px 10px; color: rgb(37, 60, 90); margin-top: 6px; }
textarea { min-height: 100px; resize: vertical; }
.login { max-width: 540px; padding: 40px; margin: 8vh auto; background: rgb(255, 255, 255); border: 1px solid rgb(214, 223, 237); border-radius: 12px; box-shadow: rgba(34, 75, 134, 0.063) 0px 12px 40px; }
.login h1 { font-size: 28px; }
.login form { margin: 26px 0px 16px; }
.login .primary { width: 100%; margin-top: 12px; }
.brandmark { background: rgb(53, 103, 214); color: rgb(255, 255, 255); font-size: 24px; font-weight: 700; border-radius: 9px; width: 64px; height: 64px; display: grid; place-items: center; margin-bottom: 24px; }
@media (max-width: 1100px) {
  .shell { grid-template-columns: 172px minmax(0px, 1fr); }
  .content { padding: 20px; }
  .workspace { grid-template-columns: 1fr; }
  .metrics { grid-template-columns: repeat(2, minmax(0px, 1fr)); }
  .alertrow { grid-template-columns: 1fr 1fr; }
  .alertrow > .actions { grid-column: 1 / -1; }
  .brand small { display: none; }
}
@media (max-width: 650px) {
  .topbar { padding: 12px 16px; height: auto; min-height: 64px; }
  .brand { font-size: 14px; }
  .brand b { font-size: 18px; padding-right: 10px; }
  .account { gap: 8px; font-size: 12px; }
  .account button { padding: 6px 10px; }
  .modulebar { padding: 8px 16px; gap: 12px; flex-wrap: wrap; }
  .modulebar > span:first-child, .modulebar small { display: none; }
  .modulebar strong { padding: 4px 0px; }
  .env { margin-left: 0px; }
  .shell { display: block; }
  aside { padding: 8px 12px; border-right: 0px; border-bottom: 1px solid rgb(217, 225, 237); }
  .navtitle, .sidefoot { display: none; }
  nav { display: flex; overflow-x: auto; gap: 6px; }
  nav a { white-space: nowrap; font-size: 13px; padding: 10px; flex-shrink: 0; }
  nav a.active { border-left: 0px; border-bottom: 3px solid rgb(53, 103, 214); padding-left: 10px; }
  .content { padding: 20px 16px; }
  .pagehead { align-items: flex-start; flex-wrap: wrap; }
  h1 { font-size: 23px; }
  .card { padding: 16px; }
  .toolbar label { width: 100%; display: block; }
  .toolbar .muted { margin-left: 0px; }
  .metrics { gap: 10px; }
  .metric { padding: 14px; }
  .metric strong { font-size: 23px; }
  .alertrow { grid-template-columns: 1fr; gap: 12px; }
  .states { grid-template-columns: repeat(2, minmax(0px, 1fr)); }
  .tasktitle .muted { margin-left: 0px; }
  .login { margin: 24px 16px; padding: 26px; }
  .prediction { flex-wrap: wrap; }
  dl { grid-template-columns: 110px 1fr; }
}
@media (max-width: 650px) {
  .tablewrap table { min-width: 680px; }
  .tablewrap { overscroll-behavior-x: contain; }
}
body { font-variant-numeric: tabular-nums; }
.section-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 12px; flex-wrap: wrap; }
.section-head h2 { margin: 0px; }
.section-head .eyebrow { margin-bottom: 4px; }
.numeric { font-size: 18px; font-weight: 650; letter-spacing: -0.3px; color: rgb(35, 60, 93); }
.patient-label { display: block; margin-top: 10px; white-space: nowrap; }
.clinical-board { grid-template-columns: minmax(0px, 1.85fr) minmax(280px, 1fr); }
.queue-heading { display: flex; justify-content: space-between; gap: 12px; margin: 18px 0px 10px; font-size: 13px; }
.queue-heading a { font-size: 12px; }
.queue-empty { border: 1px dashed rgb(204, 215, 229); background: rgb(248, 250, 253); border-radius: 6px; padding: 18px; color: rgb(77, 101, 131); }
.queue-empty span { display: block; font-size: 12px; color: rgb(100, 116, 138); margin-top: 4px; }
.queue-item { display: block; padding: 14px 0px; border-bottom: 1px solid rgb(228, 235, 243); }
.queue-item strong, .queue-item small { display: block; margin-top: 6px; }
.queue-item small { color: rgb(100, 116, 138); }
.safety-strip { display: flex; gap: 20px; align-items: center; flex-wrap: wrap; padding: 15px 18px; border: 1px solid rgb(213, 223, 236); border-radius: 7px; background: rgb(245, 248, 252); font-size: 13px; color: rgb(91, 110, 135); }
.safety-strip a { margin-left: auto; }
.segmented { display: flex; gap: 4px; padding: 3px; border: 1px solid rgb(217, 227, 238); border-radius: 7px; background: rgb(245, 248, 252); }
.segmented button { min-height: 36px; border: 0px; padding: 7px 14px; background: transparent; font-size: 13px; }
.segmented button.selected { background: rgb(53, 103, 214); color: rgb(255, 255, 255); box-shadow: rgba(36, 71, 124, 0.133) 0px 2px 5px; }
.chart-caption { font-size: 12px; color: rgb(94, 114, 138); display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin: 4px 0px 20px; }
.chart-caption > span:last-child { margin-left: auto; }
.legend-line { width: 20px; border-top: 2px solid rgb(53, 103, 214); }
.trend-grid { display: grid; grid-template-columns: repeat(3, minmax(0px, 1fr)); gap: 16px; }
.trend-tile { border: 1px solid rgb(220, 229, 239); border-radius: 8px; padding: 16px 16px 10px; min-width: 0px; background: linear-gradient(rgb(255, 255, 255) 75%, rgb(251, 252, 254)); }
.trend-title { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.trend-title > div > span { font-weight: 650; font-size: 15px; }
.trend-title small { display: block; font-size: 11px; color: rgb(100, 116, 139); margin-top: 2px; letter-spacing: 0.4px; }
.trend-title > .tag { font-size: 11px; white-space: nowrap; }
.trend-reading { display: flex; gap: 7px; align-items: baseline; font-size: 30px; line-height: 1.3; font-weight: 650; margin: 13px 0px 4px; letter-spacing: -0.6px; }
.trend-reading small { font-size: 12px; font-weight: 400; letter-spacing: 0px; color: rgb(98, 116, 138); }
.trend-reading span { font-size: 12px; font-weight: 400; letter-spacing: 0px; color: rgb(98, 116, 138); margin-left: auto; }
.trend-tile svg { display: block; width: 100%; height: auto; overflow: visible; margin-top: 8px; }
.trend-tile svg text { font: 12px "Segoe UI", sans-serif; fill: rgb(104, 123, 144); }
.observation-dot { cursor: pointer; }
.observation-dot:hover { r: 5; stroke: rgb(255, 255, 255); stroke-width: 2; }
.trend-foot { font-size: 11px; color: rgb(97, 116, 138); display: flex; align-items: center; justify-content: space-between; gap: 6px; min-height: 42px; border-top: 1px solid rgb(237, 241, 246); margin-top: 4px; }
.trend-foot button { min-height: 36px; font-size: 11px; padding: 5px 8px; background: rgb(247, 250, 255); border: 1px solid rgb(215, 227, 243); color: rgb(53, 97, 162); }
.chart-empty { min-height: 130px; display: grid; align-content: center; text-align: center; color: rgb(116, 131, 152); font-size: 14px; }
.chart-empty small { font-size: 11px; margin-top: 6px; }
.point-evidence { margin: 16px 0px; padding: 16px; border: 1px solid rgb(168, 193, 237); border-radius: 8px; background: rgb(244, 248, 255); overflow-wrap: anywhere; }
.point-evidence dl { font-size: 13px; margin-bottom: 4px; gap: 6px; }
.bar-chart { margin: 28px 0px 18px; }
.bar-row { display: grid; grid-template-columns: 100px 1fr 24px; align-items: center; gap: 12px; margin: 20px 0px; font-size: 13px; }
.bar-track { height: 20px; background: rgb(240, 244, 248); border-radius: 3px; }
.bar-track > div { height: 100%; border-radius: 3px; min-width: 0px; }
.bar-row strong { text-align: right; }
.bar-axis { display: flex; justify-content: space-between; margin-left: 112px; margin-right: 36px; border-top: 1px solid rgb(203, 214, 227); padding-top: 6px; font-size: 11px; color: rgb(97, 116, 138); }
.split-count { display: flex; border-top: 1px solid rgb(229, 235, 242); padding-top: 16px; gap: 30px; }
.split-count strong { font-size: 23px; display: block; }
.split-count span { font-size: 12px; color: rgb(98, 116, 139); }
.color-dot { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 8px; }
.table-total { background: rgb(245, 248, 252); font-weight: 650; }
.quality-table td, .quality-table th { padding: 14px 8px; }
.metric { position: relative; border-top: 3px solid rgb(150, 177, 223); }
.metric:nth-child(2) { border-top-color: rgb(200, 144, 64); }
.metric:nth-child(3) { border-top-color: rgb(105, 160, 164); }
.metric:nth-child(4) { border-top-color: rgb(164, 166, 187); }
@media (min-width: 1600px) {
  .trend-tile { padding: 18px; }
  .trend-reading { font-size: 34px; }
}
@media (max-width: 1200px) {
  .trend-grid { grid-template-columns: repeat(2, minmax(0px, 1fr)); }
  .clinical-board { grid-template-columns: 1fr; }
  .chart-caption > span:last-child { margin-left: 0px; }
}
@media (max-width: 650px) {
  .trend-grid { grid-template-columns: 1fr; }
  .trend-section, .trend-tile { padding: 14px; }
  .trend-reading { font-size: 32px; }
  .section-head { align-items: flex-start; }
  .segmented { width: 100%; }
  .segmented button { flex: 1 1 0%; min-height: 40px; }
  .quality-table { min-width: 280px !important; }
  .bar-row { grid-template-columns: 90px 1fr 24px; gap: 8px; }
  .bar-axis { margin-left: 98px; margin-right: 32px; }
  .chart-caption { font-size: 11px; }
  .point-evidence dl { grid-template-columns: 90px 1fr; }
}
.assessment-ribbon { display: grid; grid-template-columns: 1.3fr 0.8fr 1.3fr 1fr; gap: 20px; background: rgb(255, 255, 255); border: 1px solid rgb(220, 228, 239); border-radius: 8px; margin-bottom: 20px; padding: 18px 22px; align-items: center; }
.assessment-ribbon small { display: block; color: rgb(97, 116, 138); font-size: 12px; margin-bottom: 6px; }
.assessment-ribbon strong { display: block; font-size: 16px; line-height: 1.5; }
.assessment-ribbon strong span { font-size: 13px; font-weight: 400; }
.attention-text { color: rgb(170, 62, 54); }
.assessment-ribbon .button { padding: 8px 12px; font-size: 13px; white-space: nowrap; }
.tablehint { display: none; }
.trend-tile svg text { font-size: 14px; }
.trend-title small, .trend-foot { font-size: 12px; }
.trend-foot button { min-height: 44px; font-size: 12px; }
.segmented button { min-height: 44px; }
.trend-reading small, .trend-reading span { font-size: 13px; }
@media (max-width: 950px) {
  .assessment-ribbon { grid-template-columns: 1fr 1fr; gap: 18px; }
}
@media (max-width: 650px) {
  .assessment-ribbon { padding: 16px; gap: 14px; }
  .assessment-ribbon strong { font-size: 14px; }
  .assessment-ribbon small { font-size: 12px; }
  .tablehint { display: block; font-size: 12px; color: rgb(93, 115, 146); }
  .patient-worklist td:last-child, .patient-worklist th:last-child { position: sticky; right: 0px; background: rgb(255, 255, 255); box-shadow: rgba(36, 62, 99, 0.063) -4px 0px 8px; min-width: 116px; }
  .patient-worklist th:last-child { background: rgb(245, 248, 252); }
  .patient-worklist td:last-child .button { padding: 9px 10px; white-space: nowrap; }
  .trend-foot button { font-size: 12px; white-space: nowrap; }
}
.embedded-workspace { min-height: 100vh; background: rgb(243, 246, 251); }
.embed-header { min-height: 52px; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 10px 24px; background: rgb(255, 255, 255); border-bottom: 1px solid rgb(220, 228, 239); }
.embed-header strong { font-size: 16px; }
.embed-breadcrumb { margin-left: 14px; padding-left: 14px; border-left: 1px solid rgb(212, 222, 235); color: rgb(100, 116, 139); font-size: 13px; }
.embed-context { display: flex; align-items: center; gap: 16px; padding: 16px 24px 12px; flex-wrap: wrap; background: rgb(255, 255, 255); }
.embed-context > div { display: flex; align-items: center; gap: 12px; }
.embed-context strong { font-size: 18px; }
.embed-context > .muted { font-size: 13px; }
.embed-scope { margin-left: auto; font-size: 12px; color: rgb(97, 116, 138); }
.embed-tabs { display: flex; gap: 24px; background: rgb(255, 255, 255); border-bottom: 1px solid rgb(220, 228, 239); padding: 0px 24px; }
.embed-tabs button { border-width: 0px 0px 3px; border-style: none none solid; border-color: currentcolor currentcolor transparent; border-image: initial; border-radius: 0px; background: transparent; min-height: 48px; padding: 8px 4px; color: rgb(101, 117, 140); font-weight: 500; }
.embed-tabs button.active { border-bottom-color: rgb(53, 103, 214); color: rgb(36, 84, 178); font-weight: 650; }
.embed-body { padding: 20px 24px; }
.embedded-workspace .pagehead { margin-bottom: 12px; justify-content: flex-end; }
.embedded-workspace patient-detail .pagehead { min-height: 44px; }
.embedded-workspace patient-detail .notice { font-size: 12px; padding: 8px 12px; margin-bottom: 14px; }
.embedded-workspace .assessment-ribbon { margin-bottom: 16px; }
.embedded-workspace .trend-section { margin-bottom: 0px; }
.embed-wait { max-width: 640px; margin: 10vh auto; text-align: center; padding: 32px; }
.embed-wait h1 { font-size: 22px; }
.embed-symbol { height: 60px; width: 60px; display: grid; place-items: center; background: rgb(227, 236, 254); border-radius: 10px; color: rgb(53, 103, 214); font-size: 20px; font-weight: 700; margin: 0px auto 20px; }
@media (max-width: 700px) {
  .embed-header { padding: 12px 16px; }
  .embed-breadcrumb { display: none; }
  .embed-context { padding: 14px 16px; gap: 8px; }
  .embed-context > .muted { width: 100%; overflow-wrap: anywhere; }
  .embed-scope { margin-left: 0px; }
  .embed-tabs { padding: 0px 16px; gap: 16px; overflow-x: auto; }
  .embed-tabs button { white-space: nowrap; flex-shrink: 0; font-size: 13px; }
